26	const PROCESSING_FEE = 5;
27	
28	// Only the main item types. Components are priced separately: individually,
29	// or as a discounted block of 3 alike ones.
30	const BASE_PREMIUMS: Record<string, number> = {
31	  sword: 100,
32	  amulet: 60,
33	  staff: 80,
34	  potion: 40,
35	};
36	
37	const COMPONENT_TYPES = ["rune", "moonstone"];
38	const COMPONENT_BASE_PREMIUM = 25;
39	const BLOCK_SIZE = 3;
40	const BLOCK_BASE_PREMIUM = 60;
41	
42	const isComponent = (item: Item): boolean =>
43	  COMPONENT_TYPES.includes(item.type);
44	
45	// Modifiers are additive percentages of the UNMODIFIED base premium, never
46	// compounding multipliers, and are kept as exact fractions rather than float
47	// multipliers: 100 * 1.1 is 110.00000000000001 in IEEE-754. Only the final
48	// premium is rounded, so intermediate amounts stay fractional.
49	const percentOf = (amount: number, percent: number): number =>
50	  (amount * percent) / 100;
51	
52	// Modifiers are signed terms in one additive sum, so a discount is simply a
53	// negative percentage. Naming the sign keeps it from riding on a single easily
54	// overlooked "-" at a call site.
55	const discountOf = (amount: number, percent: number): number =>
56	  -percentOf(amount, percent);
57	
58	const FIRST_INSURANCE_PERCENT = 10;
59	const CURSE_PERCENT = 50;
60	const HIGH_ENCHANTMENT_PERCENT = 30;
61	const HIGH_ENCHANTMENT_THRESHOLD = 5;
62	const LOYALTY_DISCOUNT_PERCENT = 20;
63	const LOYALTY_THRESHOLD_YEARS = 2;
64	const FOLLOW_UP_DISCOUNT_PERCENT = 15;
65	
66	const basePremiumOf = (item: Item): number => BASE_PREMIUMS[item.type];
67	
68	// A group of exactly 3 alike components is offered at a block price. Any
69	// other count is priced per component.
70	const componentGroupPremium = (count: number): number =>
71	  count === BLOCK_SIZE ? BLOCK_BASE_PREMIUM : count * COMPONENT_BASE_PREMIUM;
72	
73	// Components are priced per group of alike ones, so each distinct type is
74	// counted and priced on its own.
75	const componentsPremium = (components: Item[]): number => {
76	  const distinctTypes = new Set(components.map((component) => component.type));
77	
78	  return [...distinctTypes].reduce((sum, type) => {
79	    const alike = components.filter((component) => component.type === type);
80	    return sum + componentGroupPremium(alike.length);
81	  }, 0);
82	};
83	
84	// Splits a quote's items into the two independently-priced kinds, so the
85	// main/component distinction is decided in exactly one place.
86	const partitionByComponent = (
87	  items: Item[],
88	): { mainItems: Item[]; components: Item[] } => ({
89	  mainItems: items.filter((item) => !isComponent(item)),
90	  components: items.filter(isComponent),
91	});
92	
93	// Item-specific modifiers apply to the affected item's OWN base premium, not
94	// to the policy total. They are independent: a cursed, highly enchanted item
95	// carries both, so each item sums the surcharges that apply to it.
96	const isHighlyEnchanted = (item: Item): boolean =>
97	  (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD;
98	
99	const surchargesFor = (item: Item): number => {
100	  const base = basePremiumOf(item);
101	  const curse = item.cursed ? percentOf(base, CURSE_PERCENT) : 0;
102	  const enchantment = isHighlyEnchanted(item)
103	    ? percentOf(base, HIGH_ENCHANTMENT_PERCENT)
104	    : 0;
105	
106	  return curse + enchantment;
107	};
108	
109	const itemSpecificModifiers = (mainItems: Item[]): number =>
110	  mainItems.reduce((sum, item) => sum + surchargesFor(item), 0);
111	
112	// Policy-wide modifiers are percentages of the whole policy's base premium,
113	// taken from the UNMODIFIED base so item-specific modifiers never feed into
114	// them - that is what keeps modifiers additive instead of compounding.
115	// Discounts are negative terms.
116	const qualifiesForLoyalty = (customer: Customer): boolean =>
117	  customer.yearsWithMHPCO >= LOYALTY_THRESHOLD_YEARS;
118	
119	const policyWideModifiers = (
120	  basePremium: number,
121	  customer: Customer,
122	  isFollowUp: boolean,
123	): number => {
124	  // First insurance applies to every quote, including follow-ups: the spec
125	  // treats each item in a quote as a first insurance regardless of customer
126	  // history, so this coexists with the follow-up discount.
127	  const firstInsurance = percentOf(basePremium, FIRST_INSURANCE_PERCENT);
128	  const loyalty = qualifiesForLoyalty(customer)
129	    ? discountOf(basePremium, LOYALTY_DISCOUNT_PERCENT)
130	    : 0;
131	  const followUp = isFollowUp
132	    ? discountOf(basePremium, FOLLOW_UP_DISCOUNT_PERCENT)
133	    : 0;
134	
135	  return firstInsurance + loyalty + followUp;
136	};
137	
138	const quotePremium = (
139	  step: QuoteStep,
140	  customer: Customer,
141	  isFollowUp: boolean,
142	): number => {
143	  const { mainItems, components } = partitionByComponent(step.items);
144	
145	  const basePremium =
146	    mainItems.reduce((sum, item) => sum + basePremiumOf(item), 0) +
147	    componentsPremium(components);
148	
149	  const modifiers =
150	    itemSpecificModifiers(mainItems) +
151	    policyWideModifiers(basePremium, customer, isFollowUp);
152	
153	  return basePremium + modifiers + PROCESSING_FEE;
154	};
155	
156	export const runScenario = (scenario: Scenario): ScenarioResult => {
157	  // Every contract after the customer's first earns the follow-up discount, so
158	  // a quote's premium depends on how many quotes preceded it.
159	  let quotesSoFar = 0;
160	
161	  const results = scenario.steps.map((step) => {
162	    const premium = quotePremium(step, scenario.customer, quotesSoFar > 0);
163	    quotesSoFar += 1;
164	    return { premium };
165	  });
166	
167	  return { results };
168	};
