export const runScenario = (scenario: Scenario): ScenarioResult => {
  // Every contract after the customer's first earns the follow-up discount, so
  // a quote's premium depends on how many quotes preceded it.
  let quotesSoFar = 0;

  const results = scenario.steps.map((step) => {
    const premium = quotePremium(step, scenario.customer, quotesSoFar > 0);
    quotesSoFar += 1;
    return { premium };
  });

  return { results };
};

