export const runScenario = (scenario: Scenario): ScenarioResult => {
  // Every contract after the customer's first earns the follow-up discount, so
  // a quote's premium depends on its ordinal position among the customer's
  // quotes. Every step is currently a quote step, so the step index IS that
  // ordinal. When claim steps enter the type the two diverge, and this is the
  // one place that has to learn to count quote steps specifically.
  const results = scenario.steps.map((step, quoteIndex) => ({
    premium: quotePremium(step, scenario.customer, quoteIndex > 0),
  }));

  return { results };
};
